// Serves this connector's own did:web document.
//
// Ported from Reference FAP "4-create did,chain files.json" node
// cf6fa8ed568dee0a ("Build DID Document (did:web, strict)") — adapted to
// (a) read the pre-provisioned private JWK from env.get('DSP_CONNECTOR_KEY')
// instead of generating/loading one from Mongo, (b) use
// env.get('DSP_CONNECTOR_DID') instead of a per-onboarding-record domain,
// (c) carry the SAME two-entry @context array
// (["https://www.w3.org/ns/did/v1", "https://w3id.org/security/suites/jws-2020/v1"])
// that node uses — Task 10's iam-issuance-did.spec.js proved the document
// SHAPE with a one-entry array; this real, externally-served did.json needs
// the second entry since it formally defines JsonWebKey2020.
//
// Public-JWK derivation mirrors Reference FAP tab 4's own
// "KEY → JWK private+public" node (1af2bb2509c14866): export the full JWK
// via jose, then manually strip the private components — jose.exportJWK has
// no "public-only" mode of its own, so this stripping step is required even
// though we already hold the private JWK directly (no PEM decode needed here
// since DSP_CONNECTOR_KEY is provisioned as JWK, not PEM).
function buildDidDocument(did, publicJwk, kid) {
    return {
        '@context': [
            'https://www.w3.org/ns/did/v1',
            'https://w3id.org/security/suites/jws-2020/v1'
        ],
        id: did,
        verificationMethod: [{
            id: kid,
            type: 'JsonWebKey2020',
            controller: did,
            publicKeyJwk: publicJwk
        }],
        authentication: [kid],
        assertionMethod: [kid]
    };
}

function fail(msg, statusCode, detail) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { error: detail };
    node.send(msg);
}

(async () => {
    const did = env.get('DSP_CONNECTOR_DID');
    if (!did) { fail(msg, 500, 'DSP_CONNECTOR_DID not provisioned'); return; }

    const rawKey = env.get('DSP_CONNECTOR_KEY');
    if (!rawKey) {
        node.error('[iam-issuance] DSP_CONNECTOR_KEY not set — cannot serve did.json');
        fail(msg, 500, 'connector key not provisioned');
        return;
    }

    try {
        const privateJwk = typeof rawKey === 'string' ? JSON.parse(rawKey) : rawKey;
        const alg = privateJwk.alg || 'ES256';
        const kid = did + '#key-1';

        const keyLike = await jose.importJWK(privateJwk, alg);
        const publicJwk = await jose.exportJWK(keyLike);
        delete publicJwk.d;
        delete publicJwk.p;
        delete publicJwk.q;
        delete publicJwk.dp;
        delete publicJwk.dq;
        delete publicJwk.qi;
        publicJwk.key_ops = ['verify'];
        publicJwk.alg = alg;
        publicJwk.kid = kid;

        msg.payload = buildDidDocument(did, publicJwk, kid);
        msg.headers = { 'Content-Type': 'application/json' };
        msg.statusCode = 200;
        node.send(msg);
    } catch (err) {
        node.error('[iam-issuance] did.json build failed: ' + err.message, msg);
        fail(msg, 500, 'internal error building did.json');
    }
})();
return null;

// Static OID4VCI issuer metadata — minimal surface (single credential
// type: this connector's own Participant VC). No dynamic per-holder logic;
// this is a discovery document only, per the OpenID4VCI
// "openid-credential-issuer" well-known convention.
const did = env.get('DSP_CONNECTOR_DID') || '';

// did:web:<domain>[:<path>...] → https://<domain>/<path>... — same mapping
// convention as dsp-iam-prep's didWebToUrl in facis-dsp-iam-verify.json.
function didWebToOrigin(d) {
    const parts = (d || '').split(':');
    if (parts[0] !== 'did' || parts[1] !== 'web') return '';
    const segments = parts.slice(2).map(decodeURIComponent);
    const domain = segments[0];
    const p = segments.slice(1);
    return p.length === 0 ? 'https://' + domain : 'https://' + domain + '/' + p.join('/');
}

const origin = didWebToOrigin(did);

msg.payload = {
    credential_issuer: did,
    credential_endpoint: origin + '/iam/oid4vci/credential',
    credential_configurations_supported: {
        ParticipantCredential: {
            format: 'jwt_vc_json',
            scope: 'ParticipantCredential',
            credential_definition: {
                type: ['VerifiableCredential', 'gx:LegalParticipant']
            }
        }
    }
};
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return msg;

// Minimal Bearer-presence guard. This repo does not have a full
// Keycloak-JWKS verification pattern anywhere yet (dsp-iam-verify.json
// verifies VP/VC tokens presented BY callers, not bearer access tokens
// presented TO this issuance endpoint), so a presence check is the honest,
// minimal scope here — do not invent a JWKS verification flow that doesn't
// exist elsewhere in this codebase.
const authHeader = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const hasBearer = /^Bearer\s+\S+/i.test(authHeader.trim());

if (!hasBearer) {
    msg.statusCode = 401;
    msg.headers = { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' };
    msg.payload = {
        '@type': 'dspace:Error',
        'dspace:code': 'missing_authorization',
        'dspace:reason': ['Authorization: Bearer <token> header is required']
    };
    return [null, msg];
}
return [msg, null];

// Build + sign this connector's own Participant VC (self-issuance), then
// hand off to the GXDCH notary/compliance call chain.
//
// Ported from Reference FAP "8-create VCs.json" node e720bc9a0b83475e
// ("Create & sign Participant VC") — adapted to (a) self-issue about THIS
// connector's own did:web identity (env.get('DSP_CONNECTOR_DID')) instead of
// an onboarding company's per-record domain, (b) read the private JWK from
// env.get('DSP_CONNECTOR_KEY') instead of Mongo-stored recordDetails, (c)
// sign a jwt_vc_json via jose.SignJWT instead of an LD-Proof —
// @gaia-x/json-web-signature-2020 is intentionally NOT one of this node's
// libs, since the OID4VCI metadata this tab serves
// (dsp-iam-issuance-oidc-meta-fn) advertises format "jwt_vc_json", not
// "ldp_vc".
//
// Outputs: [0] GXDCH notary configured → dsp-iam-issuance-vc-notary (http
// request), [1] notary not configured (or a hard failure) → straight to
// dsp-iam-issuance-vc-push.
const did = env.get('DSP_CONNECTOR_DID');
if (!did) {
    node.error('[iam-issuance] DSP_CONNECTOR_DID not set');
    msg.statusCode = 500;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { error: 'connector DID not provisioned' };
    node.send([null, msg]);
    return;
}

const rawKey = env.get('DSP_CONNECTOR_KEY');
if (!rawKey) {
    node.error('[iam-issuance] DSP_CONNECTOR_KEY not set — cannot sign Participant VC');
    msg.statusCode = 500;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { error: 'connector key not provisioned' };
    node.send([null, msg]);
    return;
}

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const kid = did + '#key-1';
const issuanceDate = new Date().toISOString();
const countryCode = body.countryCode || 'DE';

const vc = {
    '@context': [
        'https://www.w3.org/2018/credentials/v1',
        'https://w3id.org/security/suites/jws-2020/v1'
    ],
    type: ['VerifiableCredential', 'ParticipantCredential'],
    id: kid,
    issuer: did,
    issuanceDate: issuanceDate,
    credentialSubject: {
        id: did,
        type: 'gx:LegalParticipant',
        'gx:legalName': body.legalName || 'FACIS IoT-AI DSP Connector',
        'gx:legalAddress': { 'gx:countrySubdivisionCode': countryCode },
        'gx:headquarterAddress': { 'gx:countrySubdivisionCode': countryCode }
    }
};

(async () => {
    try {
        // Light structural JSON-LD sanity check before signing/notarizing.
        // Best-effort only: jsonld.expand() resolves remote @context
        // documents over the network, which this pod may not be able to
        // reach — a failure here is logged but never blocks self-issuance
        // (mirrors this codebase's warn-not-enforce posture, e.g.
        // DSP_STATUS_LIST_MODE / DSP_VERIFIER_MODE defaults).
        try {
            await jsonld.expand(vc);
        } catch (ldErr) {
            node.warn('[iam-issuance] VC JSON-LD context did not expand cleanly (non-fatal): ' + ldErr.message);
        }

        const privateJwk = typeof rawKey === 'string' ? JSON.parse(rawKey) : rawKey;
        const alg = privateJwk.alg || 'ES256';
        const key = await jose.importJWK(privateJwk, alg);

        const jti = 'urn:uuid:' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
        const vcJwt = await new jose.SignJWT({ vc: vc })
            .setProtectedHeader({ alg: alg, kid: kid, typ: 'vc+jwt' })
            .setIssuer(did)
            .setSubject(did)
            .setJti(jti)
            .setIssuedAt()
            .sign(key);

        msg.vcRecord = { did: did, kid: kid, jti: jti, vc: vc, vcJwt: vcJwt, issuedAt: issuanceDate };

        const notaryUrl = env.get('DSP_GXDCH_NOTARY_URL');
        if (notaryUrl) {
            msg.url = notaryUrl;
            msg.headers = { 'Content-Type': 'application/json' };
            msg.payload = { vc: vcJwt };
            node.send([msg, null]);
        } else {
            msg.vcRecord.gxdch = { notary: 'skipped (DSP_GXDCH_NOTARY_URL not set)', compliance: null };
            node.send([null, msg]);
        }
    } catch (err) {
        node.error('[iam-issuance] Participant VC sign failed: ' + err.message, msg);
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'application/json' };
        msg.payload = { error: 'internal error signing Participant VC' };
        node.send([null, msg]);
    }
})();
return null;

// Capture the GXDCH notary response, then decide whether to also call
// GXDCH compliance. Ported (loosely) from Reference FAP "9-create VP.json"'s
// compliance hand-off pattern — adapted to a single self-issued VC instead
// of a 3-VC VP bundle (participant + T&C + LRN), since this connector only
// self-issues its own Participant VC.
//
// The upstream dsp-iam-issuance-vc-notary http-request node deliberately
// keeps senderr:false: that is the setting that makes Node-RED forward an
// errored call (unreachable/refused/timeout GXDCH endpoint) down this same
// wire at all (senderr:true routes errors ONLY to a Catch node — this tab
// has none — which would silently drop the message and reproduce the exact
// hang-to-504 bug fixed in dsp-iam-issuance-vc-push). The tradeoff: a
// network-level failure lands here with a non-numeric msg.statusCode
// (err.code, e.g. 'ECONNREFUSED') instead of a real HTTP status, so it must
// be told apart from an actual (even error) HTTP response before being
// treated as notary output.
msg.vcRecord.gxdch = msg.vcRecord.gxdch || {};
if (typeof msg.statusCode !== 'number') {
    node.error('[iam-issuance] GXDCH notary call failed: ' + msg.payload, msg);
    msg.statusCode = 502;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { error: 'GXDCH notary call failed' };
    delete msg.vcRecord;
    return [null, msg];
}
msg.vcRecord.gxdch.notary = { statusCode: msg.statusCode, body: msg.payload };

const complianceUrl = env.get('DSP_GXDCH_COMPLIANCE_URL');
if (complianceUrl) {
    msg.url = complianceUrl;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': 'https://www.w3.org/2018/credentials/v1',
        type: 'VerifiablePresentation',
        verifiableCredential: [msg.vcRecord.vcJwt]
    };
    return [msg, null];
}
msg.vcRecord.gxdch.compliance = 'skipped (DSP_GXDCH_COMPLIANCE_URL not set)';
return [null, msg];

// Final stage — reached from three possible upstream branches
// (notary-skipped, compliance-skipped after notary ran, or compliance
// actually called) PLUS the error paths of dsp-iam-issuance-vc-fn and
// dsp-iam-issuance-vc-notary-fn (missing DID/key, signing failure, or a
// GXDCH network-level failure) — those already build a complete,
// correctly-coded msg.statusCode/headers/payload and clear msg.vcRecord
// as the "this is a pre-formed error, do not touch" signal. Guard on that
// first: dereferencing msg.vcRecord.gxdch below with no VC record present
// throws (TypeError: Cannot read properties of undefined), which Node-RED
// swallows without forwarding anything downstream — the request then hangs
// until the ingress's 120s proxy-read-timeout fires a 504 instead of the
// real error being returned immediately.
if (!msg.vcRecord) {
    return msg;
}

// msg.vcRecord.gxdch.compliance may already be set to a 'skipped (...)'
// string (notary-skipped or compliance-skipped branch) or may still be
// undefined (meaning we just came back from the real compliance
// http-request call and need to capture it — success or failure).
//
// GXDCH http-request nodes run with senderr:false (legacy Node-RED
// behaviour, deliberately kept — see dsp-iam-issuance-vc-notary-fn's
// comment): on a network-level failure (unreachable/refused/timeout) the
// node still forwards the message down this same wire, but msg.statusCode
// is then err.code (a non-numeric string like 'ECONNREFUSED'), not a real
// HTTP status. A numeric msg.statusCode means an actual HTTP response came
// back (2xx-5xx are all fine to record as-is here).
if (msg.vcRecord.gxdch.compliance === undefined) {
    if (typeof msg.statusCode !== 'number') {
        node.error('[iam-issuance] GXDCH compliance call failed: ' + msg.payload, msg);
        msg.statusCode = 502;
        msg.headers = { 'Content-Type': 'application/json' };
        msg.payload = { error: 'GXDCH compliance call failed' };
        return msg;
    }
    msg.vcRecord.gxdch.compliance = { statusCode: msg.statusCode, body: msg.payload };
}

// Small in-memory handoff queue — Task 13's hub tab drains this and
// persists to Mongo; this tab only issues (single-responsibility, matches
// how dsp-iam-verify.json never itself performs Mongo writes for identities).
const pending = global.get('identityHubPending') || [];
pending.push(msg.vcRecord);
global.set('identityHubPending', pending);

msg.payload = {
    format: 'jwt_vc_json',
    credential: msg.vcRecord.vcJwt
};
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return msg;
